"""Evidence-bound Chinese reports; does not infer or train models."""
from common import *
def table(df):return df.to_markdown(index=False,floatfmt='.8g')
def main():
    c=cfg();a=read(P/'outputs/SUMMARY.json');m=rd(P/'outputs/METRICS.csv');g=rd(P/'outputs/GATE_STATISTICS.csv');cor=rd(P/'outputs/GATE_CORRELATIONS.csv');pairs=rd(P/'outputs/CROSS_SEED_GATES.csv');ps=rd(P/'outputs/PERMUTATION_SUMMARY.csv')
    header=f"基准提交：`{BASE}`。协议SHA256：`{sha(P/'configs/frozen_protocol.json')}`。\n\n六个实例按原始F2的Validation成绩筛选。本轮是筛选后机制诊断，不能代表一般随机初始化或独立Test。每个实例205个起点、4920个查询、251个去重目标时刻；重叠窗口不构成独立统计样本。不读取Assessment/Test，不训练、不更新任何参数。\n\n"
    sections={
    '01_六种子门控权重行为.md':"# 六种子门控行为\n\n"+table(g)+"\n\n沿用J的描述性dynamic规则：SD(ddof=1)>0.001且range>0.01，低/高饱和定义g<0.1/g>0.9；这些不是性能成功门槛。g是LSTM分支比例，1−g是CNN比例。每个历史窗口只有一个g，广播至48×64编码表示，不是为24个未来步各自生成g。完整Train门控也已逐点保存；B2只由1380个Train历史输入计算。\n",
    '02_门控与历史工况关系.md':"# 门控与历史工况\n\n"+table(cor)+"\n\n## 相同输入的跨Seed对应\n\n"+table(pairs)+"\n\n五项真实输入是48个历史bin的标准化工况均值，原始单位均值并列保存。电流波动指历史各bin内电流标准差的均值，并非另行计算的整个24h总波动。五项工况未接受电压EWMA。Train三分位阈值与J逐位一致，分组及空组保存在GATE_STRATA.csv，没有依据Validation误差调整。相关性属于模型数学输入依赖，不是物理因果作用；不报告p值。不同Seed的权重函数可在路径内部表示不同的情况下获得相近预测，不能要求绝对g相同。\n",
    '03_固定门控反事实结果.md':"# 固定门控反事实\n\n"+table(m[m['mode'].isin(['B0','B1','B2'])][['seed','mode','RMSE_mV','delta_RMSE_vs_B0_mV','delta_RMSE_vs_B0_percent','prediction_change_RMS_mV','prediction_change_max_mV']])+f"\n\n固定0.5后{a['B1_worse_count']}/6个Seed的RMSE增加；固定Train均值后{a['B2_worse_count']}/6增加。六Seed等权平均变化分别{a['B1_mean_delta_mV']:.9f}、{a['B2_mean_delta_mV']:.9f}mV。正值表示相对B0变差。平均只描述这六个已筛选实例。\n\nB1是同一已训练F2的推理替换，不是独立训练F1。B2是各自Train门控输出的float64均值，在hook中转为float32；均值和实际使用值均保存。冻结网络的其他部分已经与动态门控共同训练，替换可造成训练/推理条件不一致，因此不是独立结构收益估计。\n",
    '04_门控置换实验结果.md':"# 门控对应关系置换\n\n"+table(ps)+f"\n\n十个置换随机种子在首次前向前冻结，均为205个窗口的无固定点置换。每窗口都使用别的窗口的g，严格保留每Seed的门控分布；不使用标签或未来工况制定置换。所有10次结果公开，未择优。共有{a['permutation_worse_runs']}/{a['permutation_runs']}次置换RMSE增加；{a['permutation_mean_worse_seed_count']}/6个Seed的10次平均RMSE增加，平均变化{a['C_mean_delta_mV']:.9f}mV。\n\n相同验证输入与路径保留，每次hook均finally移除，state_dict逐字节身份不变且正常预测逐点恢复。重复置换仅作稳定性诊断，不能把60次当独立模型或因果收益证据。\n",
    '05_六种子完整指标对比.md':"# 完整指标\n\n"+table(m[m['mode'].isin(['B0','B1','B2'])][['seed','mode','RMSE_mV','MAE_mV','R2','endpoint_RMSE_mV','target_time_equal_RMSE_mV','P95_mV','P99_mV','max_abs_error_mV']])+"\n\n全部78组（每Seed的B0/B1/B2与10次置换）见outputs/METRICS.csv，逐步误差见HORIZON_METRICS.csv，全部逐点预测见outputs/predictions。单位只恢复一次，R²为物理ΔV口径；目标时刻等权先在每个target_row平均平方误差，再对251个目标等权开根号，不先平均预测。所有4920点及极值保留。预测变化幅度与精度变化分列，不能混淆。\n",
    '06_动态门控独立贡献证据判断.md':f"# 独立贡献判断\n\n1. {a['dynamic_seed_count']}/6个实例达到J预先定义的描述性动态标准，实际g并非固定常数。分布与工况相关系数见01/02，接近0.5和饱和程度逐Seed报告。\n2. 相同输入的15对Seed门控秩相关范围{a['minimum_cross_seed_gate_rho']:.6f}～{a['maximum_cross_seed_gate_rho']:.6f}；不能仅凭平均曲线宣布所有Seed规律一致，完整符号及振幅见02。\n3. 固定0.5后{a['B1_worse_count']}/6个变差。\n4. 固定Train均值后{a['B2_worse_count']}/6个变差。\n5. 置换均值变差{a['permutation_mean_worse_seed_count']}/6个，全部重复变差{a['permutation_worse_runs']}/60次。不能把其中个别有利结果写成普遍增益。\n6. 平均RMSE变化B1={a['B1_mean_delta_mV']:.9f}mV，B2={a['B2_mean_delta_mV']:.9f}mV，C={a['C_mean_delta_mV']:.9f}mV。应结合03的相对变化和尾部指标判断规模，不能把“预测有变化”写成“大幅提高精度”。本轮未制定新的事后增益门槛。\n7. J的Seed42门控和B0逐点复现；B1指标独立与J对照。J原结论仍为动态效果未解决：三个旧Seed平均学习门控仅约0.002019mV优势且方向混合。P2九次训练G0/G1/G2均值8.387048/8.349936/9.143434mV，G2平均反而差0.756386/0.793498mV，原0.5mV及逐Seed门槛未通过。本轮无权重训练，不能推翻P2。\n8. 不能将“动态门控独立稳定提高精度”写成已证实核心贡献。可以写为可复现的历史工况依赖融合设计，以及筛选实例上的门控行为/推理敏感性诊断。B0本身用于筛选六实例，因此这些实例对B0较有利是可能的选择偏差，不能将本轮对照升级为无偏估计。\n9. 若论文必须坚持独立精度收益主张，必须有合格的重新训练对照，但目前P2已经提供负面证据，不能为挽救主张盲目追加筛选。优先收口已有证据；下一步最小可选方案见07，本轮未执行。\n",
    '07_下一阶段最小必要消融实验方案.md':"# 下一阶段最小必要方案\n\n当前建议：不再为追求动态门控正面结果追加训练，先把双路径预测性能、真实门控变化、有限推理影响和P2未获独立增益完整写入论文。独立训练消融不是本轮完成条件，现有P2九次实验已经完成这类核心对照。\n\n只有负责人仍要求检验新的、明确的可迁移收益假设时，才另行授权：最小为3个训练前固定且未经筛选的新Seed × 3组（固定0.5、历史输入不变的全局学习比例、原动态门控）共9次CPU/GPU正式训练，复用P2公平初始化/相同数据、超参数、停止规则与原0.5mV工程门槛，不新增结构或搜索。它是新的探索性重复，三个Seed并不足以宣称显著性或一般初始化性能。不得使用本轮六个按B0筛选的Seed作为无偏配对样本。\n\n证据缺口是不同融合规则在重新训练后能否稳定获益，而不是当前g是否变化。停止条件：达到预注册训练预算立即结束，保留全部失败与不利结果，未过全部门槛就收回独立收益主张；不得加Seed直到正面。Development已反复使用，新分析不能升级成独立确认性Test。本轮没有访问Assessment/Test，也不为未来方案提前访问。\n"
    }
    for name,body in sections.items():txt('reports/'+name,header+body)
    txt('README.md',"# 六个筛选F2实例的门控机制审计\n\n"+header+"本阶段仅前向推理；原始权重、历史输出、J及P2结论只读。先查outputs/audits再续做，禁止重复冻结协议。\n\n运行（项目环境Python3.11.9 / Torch2.6.0+cu124 / PF1.8.0 / 原RTX3070 CUDA协议）：\n\n```powershell\npython -B scripts/prepare.py  # 已完成；不能重新冻结\npython -B -m unittest discover -s tests -v\npython -B scripts/run_inference.py  # 完成的Seed会严格检查后跳过\npython -B scripts/analyze.py\npython -B scripts/plot_figures.py\npython -B scripts/verify.py\npython -B scripts/write_reports.py\npython -B scripts/seal.py\n```\n\n所有命令设置PYTHONUTF8=1和PYTHONDONTWRITEBYTECODE=1。输入为历史nrows=3007→过滤3005行协议构建并已冻结的合法Train/Validation张量；本轮不打开原始CSV、不重新构造样本。SHA协议与历史保护表位于configs及outputs/audits。临时hook每次移除；每个干预后正常预测逐点恢复。独立verify不调用主指标函数，以标量运算重算全部CSV并检查键/真值/时间/门控分布。完整图源数据及索引见outputs/FIGURE_INDEX.csv。最终SHA256清单见outputs/DELIVERY_MANIFEST.json。\n")
    index=[dict(figure=f'figures/{i:02d}_{name}',csv=src,script='scripts/plot_figures.py',scientific_scope='selected-instance Development Validation diagnosis') for i,name,src in [
        (1,'gate_over_time','outputs/ALL_VALIDATION_GATES.csv'),(2,'gate_current_variability','outputs/ALL_VALIDATION_GATES.csv'),(3,'fixed_gate_RMSE','outputs/METRICS.csv'),(4,'permutation_RMSE','outputs/METRICS.csv'),(5,'horizon_RMSE','outputs/HORIZON_METRICS.csv'),(6,'fixed_window_predictions','outputs/FIGURE_WINDOW_DATA.csv'),(7,'unfavorable_windows','outputs/FIGURE_WINDOW_DATA.csv')]]
    cs('outputs/FIGURE_INDEX.csv',index)
if __name__=='__main__':main()
